public ListNode? GetIntersectionNodeBrute(ListNode? a, ListNode? b)
{
    while (a != null)
    {
        ListNode? currB = b;
        while (currB != null)
        {
            if (a == currB) return a;
            currB = currB.Next;
        }
        a = a.Next;
    }
    return null;
}

public ListNode? GetIntersectionNode(ListNode? a, ListNode? b)
{
    if (a == null || b == null) return null;
    ListNode? pA = a, pB = b;
    while (pA != pB)
    {
        pA = pA == null ? b : pA.Next;
        pB = pB == null ? a : pB.Next;
    }
    return pA;
}
